-- =====================================================================
-- V33: Add Toss customerKey to billing_keys
--
-- Toss billing charge API (/v1/billing/{billingKey}) requires the same
-- customerKey that was used at billing key issuance time. Without this
-- column, charge calls fail with NOT_FOUND_CUSTOMER_KEY.
--
-- customerKey is generated by Lumie at registration time (deterministic
-- "lumie-tenant-{tenantId}" string) and stored alongside the Toss-issued
-- pg_billing_key.
-- =====================================================================

ALTER TABLE billing_keys
    ADD COLUMN IF NOT EXISTS customer_key VARCHAR(255);

COMMENT ON COLUMN billing_keys.customer_key IS
    'Toss customerKey used at billing key issuance. Must be passed back on every charge call.';
